 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a rectangular color strip: several identical, adjacent rows of
    # nonzero palette colors.
    strips = []
    for y in range(h):
        xs = [x for x, v in enumerate(grid[y]) if v != 0]
        if not xs:
            continue
        lo, hi = min(xs), max(xs)
        vals = grid[y][lo:hi + 1]
        if all(v != 0 for v in vals):
            strips.append((y, lo, hi, vals))
    palette = None
    for y, lo, hi, vals in strips:
        run = [y]
        for yy in range(y + 1, h):
            if grid[yy][lo:hi + 1] == vals:
                run.append(yy)
            else:
                break
        if len(run) >= 2 and (palette is None or len(run) > palette[0]):
            palette = (len(run), y, lo, hi, vals)
    if palette is None:
        return [row[:] for row in grid]
    _, py, px0, px1, colors = palette

    # The 1-colored figure is the stamp. Ignore cells in the palette strip.
    pts = [(y, x) for y in range(h) for x in range(w)
           if grid[y][x] == 1 and not (py <= y < py + _palette_height(grid, py, px0, px1, colors)
                                       and px0 <= x <= px1)]
    if not pts or 1 not in colors:
        return [row[:] for row in grid]
    y0, y1 = min(y for y, _ in pts), max(y for y, _ in pts)
    x0, x1 = min(x for _, x in pts), max(x for _, x in pts)
    stamp = [[grid[y][x] == 1 for x in range(x0, x1 + 1)]
             for y in range(y0, y1 + 1)]
    sh, sw = len(stamp), len(stamp[0])
    anchor = colors.index(1)

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        top = y0 + (i - anchor) * sh
        for dy in range(sh):
            for dx in range(sw):
                yy, xx = top + dy, x0 + dx
                if 0 <= yy < h and stamp[dy][dx]:
                    out[yy][xx] = color
    return out


def _palette_height(grid, y, x0, x1, vals):
    n = 0
    while y + n < len(grid) and grid[y + n][x0:x1 + 1] == vals:
        n += 1
    return n
